#include <bits/stdc++.h>
using namespace std;
#define ll long long

bool check(vector<ll>&a, int m, int p,int mid){
    ll ans = a[p + 2*mid] + a[p+2*mid + 1] > 3 * a[m- 2*p - mid - 1];
    return ans;
}
int main() {
	// your code goes here
    ios::sync_with_stdio(0);
    cin.tie(0);
    
    int t;
    cin >> t;
    
    while(t--){
        
        int n;
        cin >> n;
        
        int m = 3*n;
        vector<ll>a(m),b(m+1,0);
        for (int i = 0; i < m; i++){
            cin >> a[i];
        }
        
        sort(a.begin(),a.end(),greater<ll>());
        for (int i = 0; i < m; i++){
            b[i+1] = b[i] + a[i];
        }
        
        ll ans = 0;
        for (int p = 0; p <= n; p++){
            int s = 0, e = n - p - 1;
            while(s <= e){
                int mid = (s + e)/2;
                if (check(a,m,p,mid)){
                    s = mid + 1;
                }
                else{
                    e = mid - 1;
                }
            }
            
            ll x = 2*b[p] + b[p+2*s] + 3*b[m-2*p-s];
            ans = max(ans,x);
        }
        cout << ans << endl;
    }
}
